parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "ACTION_NEEDED",
        "JOB_CONFIRMATION",
        "JOB_REJECTION",
        "RECRUITER_REPLY",
        "JOB_ALERT",
        "FYI",
        "IGNORE"
      ],
      "description": "The single best-fit category for this email"
    },
    "confidence": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "How confident the model is in the chosen category, 0-100"
    },
    "summary": {
      "type": "string",
      "description": "One tight sentence summarizing the email"
    },
    "suggested_task": {
      "type": [
        "string",
        "null"
      ],
      "description": "A concrete next action for the user, or null if none exists"
    },
    "company": {
      "type": [
        "string",
        "null"
      ],
      "description": "Employer name for JOB_CONFIRMATION, JOB_REJECTION, or RECRUITER_REPLY when identifiable, else null"
    }
  },
  "required": [
    "category",
    "confidence",
    "summary",
    "suggested_task",
    "company"
  ]
}

parameters.jsCode:
const html = $json.body?.content || $json.bodyPreview || '';

// Listings are delimited by data-test-id="job-card" (measured: 6 per digest email)
const parts = html.split('data-test-id="job-card"').slice(1);

const seen = new Set();
const cards = [];
for (const part of parts) {
  const urlMatch = part.match(/linkedin\.com\/comm\/jobs\/view\/(\d+)/);
  if (!urlMatch) continue;
  const jobId = urlMatch[1];
  if (seen.has(jobId)) continue;
  seen.add(jobId);
  // NOTE: field named listing_url (not url) - Notion getAll responses have
  // their own 'url' property (the Notion page URL); colliding names would be
  // clobbered when this item is merged with a Notion response downstream.
  const listingUrl = `https://www.linkedin.com/jobs/view/${jobId}/`;
  const cardText = part
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1200);
  cards.push({ job_id: jobId, listing_url: listingUrl, card_text: cardText });
}
return [{ json: { cards } }];

const existingRows = $input.all().map(item => ({
  title: item.json.property_job || item.json.Job || '',
  company: item.json.property_company || item.json.Company || ''
})).filter(r => r.title || r.company);

const cards = $('Split Job Cards').item.json.cards;
return [{ json: { cards, existing_rows: existingRows } }];

function normTitle(t) {
  return (t || '').toLowerCase().replace(/\s+/g, ' ').trim();
}
function normCompany(c) {
  return (c || '').toLowerCase()
    .replace(/\b(ltd|limited|plc|group|inc|llc|co|corporation|corp)\b\.?/g, '')
    .replace(/[.,]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
// "Weatherbys Private Bank" vs "Weatherbys Ltd" only share a normalised
// prefix after suffix-stripping ('weatherbys private bank' vs 'weatherbys'),
// not the full string - exact-match on the normalised pair missed this live
// case entirely. Substring containment on the normalised names is the
// smallest fix that still catches it without pulling in a fuzzy-match lib.
function companiesMatch(a, b) {
  const na = normCompany(a), nb = normCompany(b);
  if (!na || !nb) return false;
  return na === nb || na.includes(nb) || nb.includes(na);
}

const listings = $json.output.listings || [];
const cards = $('Collect Context').item.json.cards;
const existingRows = $('Collect Context').item.json.existing_rows;

const kept = []; // { title, company } already emitted, for within-batch check
const results = [];
for (const entry of listings) {
  const card = cards[entry.listing_index - 1];
  if (!card) continue;
  const t = normTitle(entry.title);
  const isDup = kept.some(k => k.t === t && companiesMatch(k.company, entry.company));
  if (isDup) continue; // same role posted twice in this email
  kept.push({ t, company: entry.company });
  results.push({
    json: {
      job_id: card.job_id,
      listing_url: card.listing_url,
      title: entry.title,
      company: entry.company,
      location: entry.location,
      salary_raw: entry.salary_raw,
      seniority: entry.seniority,
      fit_score: entry.fit_score,
      why: entry.why,
      existing_rows: existingRows
    }
  });
}
return results;

function normTitle(t) {
  return (t || '').toLowerCase().replace(/\s+/g, ' ').trim();
}
function normCompany(c) {
  return (c || '').toLowerCase()
    .replace(/\b(ltd|limited|plc|group|inc|llc|co|corporation|corp)\b\.?/g, '')
    .replace(/[.,]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
// Same substring-containment rule as Split Scored Listings, so a role that
// slipped through under one company-name variant this week still matches an
// existing row filed under a slightly different variant last week.
function companiesMatch(a, b) {
  const na = normCompany(a), nb = normCompany(b);
  if (!na || !nb) return false;
  return na === nb || na.includes(nb) || nb.includes(na);
}

// $json here is Check Existing Job's Notion lookup (often empty), NOT the listing.
// The listing is the current Loop Over Items batch (batchSize 1).
const L = $('Loop Over Items').first().json;
const myTitle = normTitle(L.title);
// existing_rows was carried forward from Collect Context, not looked up
// cross-node here - avoids depending on a node executing in another branch.
const existing = L.existing_rows || [];

let isDup = false;
for (const r of existing) {
  if (!r.title && !r.company) continue;
  if (normTitle(r.title) === myTitle && companiesMatch(r.company, L.company)) {
    isDup = true;
    break;
  }
}

return { json: { ...L, is_near_duplicate: isDup } };

// Sender rules (step 1 of the chain). Hard decisions for known automated senders, keyed by exact lowercase address.
// Load your own sender map here. RULES = [category, source]; only low-risk categories (JOB_ALERT, IGNORE) belong here.
// HINTS = the mail folder you file a sender under; a hint only, never a decision: it is passed to the Jev stage and the fallback LLM.
// Protected categories (ACTION_NEEDED, JOB_*, RECRUITER_REPLY) never get rules.
const RULES = {
  "alerts@jobboard.example.com": ["JOB_ALERT", "map"],
  "news@shop.example.com": ["IGNORE", "map"],
  "promo@store.example.com": ["IGNORE", "map"]
};
// Load your own sender map here.
const HINTS = {
  "billing@bank.example.com": "Money",
  "orders@shop.example.com": "Orders & Deliveries",
  "friend@mail.example.com": "INBOX - people"
};

const from = String($json.from || '').trim().toLowerCase();
const r = RULES[from];
return { json: { ...$json, _rule_cat: r ? r[0] : '', _rule_source: r ? r[1] : '', _folder_hint: HINTS[from] || '' } };

// Builds the Jev (TypeSafe) request using a generic base rulebook. Replace with a rulebook learned from your own mail.
const RB = {
 "instructions": "Classify the email into exactly one category.",
 "criteria": {
  "ACTION_NEEDED": "A non-job-search message that needs the reader to respond or act, such as replying, paying, scheduling or deciding.",
  "JOB_CONFIRMATION": "An automated acknowledgement that a job application was received.",
  "JOB_REJECTION": "A message that clearly declines a job application.",
  "RECRUITER_REPLY": "A real person at a recruiter or employer writing personally to the reader: replying, reaching out or arranging a call. Not an automated notice.",
  "JOB_ALERT": "An automated digest or alert listing job openings from a job board.",
  "FYI": "Informational mail that needs no action and is not junk, such as newsletters the reader follows, receipts and non-job confirmations.",
  "IGNORE": "Spam, promotions and low-value automated notifications."
 }
};
const body = (($json.body && $json.body.content) || $json.bodyPreview || '').toString().replace(/<[^>]+>/g, ' ').slice(0, 1500);
const hint = $json._folder_hint ? '\nSender usually files under: ' + $json._folder_hint + ' (a hint only, decide from the content)' : '';
const state = 'From: ' + ($json.from || '') + hint + '\nSubject: ' + ($json.subject || '') + '\nBody: ' + body;
return { json: { ...$json, _jev_body: { state, model: 'jev-latest', questions: { category: { type: 'choice', instructions: RB.instructions, criteria: RB.criteria } } } } };

// Jev decides only when top probability >= 0.90 AND the choice is not a protected category (those create tracker rows
// and always go to the fallback LLM). Any Jev error / odd response = unsure.
const PROT = ['ACTION_NEEDED','JOB_REJECTION','RECRUITER_REPLY','JOB_CONFIRMATION'];
const email = { ...$('Prepare Jev').item.json }; delete email._jev_body;
let cat = '', p = 0;
try {
  const a = $json.answers.category;
  p = Math.max(...Object.values(a.probabilities));
  cat = a.choice;
} catch (e) { cat = ''; }
const handled = !!cat && p >= 0.90 && !PROT.includes(cat);
return { json: { ...email, _jev_cat: handled ? cat : '', _jev_p: p, _jev_handled: handled } };

// Normalizer: keeps the old LLM-chain contract ({ output: {category, confidence, summary, suggested_task, company} })
// so every $('Classify Email').item.json.output.* downstream keeps working. decided_by = rule | jev | fallback.
if ($json.output) return { json: { output: $json.output, decided_by: 'fallback' } };
const byRule = !!$json._rule_cat;
return { json: {
  output: {
    category: byRule ? $json._rule_cat : $json._jev_cat,
    confidence: byRule ? 100 : Math.round(($json._jev_p || 0) * 100),
    summary: $json.subject || '(no subject)',
    suggested_task: null,
    company: null
  },
  decided_by: byRule ? 'rule' : 'jev',
  rule_source: byRule ? ($json._rule_source || 'learned') : undefined
} };
